import { DeleteObjectCommand, GetObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { Global, Module } from '@nestjs/common';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { getEnv } from '../config/env';

/** Private object storage. Keys are generated by the app and never contain user-supplied names. */
export abstract class FileStorage {
  abstract put(key: string, body: Buffer, contentType: string): Promise<void>;
  abstract get(key: string): Promise<Buffer>;
  abstract delete(key: string): Promise<void>;
}

const SAFE_KEY = /^[a-z0-9-]+(\/[a-z0-9-]+)*$/;

function assertSafeKey(key: string) {
  if (!SAFE_KEY.test(key)) throw new Error('Invalid storage key');
}

/** Files on this server's disk, outside any public directory. */
export class LocalFileStorage extends FileStorage {
  private readonly root = path.resolve(getEnv().STORAGE_LOCAL_DIR);

  private pathFor(key: string) {
    assertSafeKey(key);
    const full = path.resolve(this.root, key);
    if (!full.startsWith(this.root + path.sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, body: Buffer) {
    const full = this.pathFor(key);
    await mkdir(path.dirname(full), { recursive: true, mode: 0o700 });
    await writeFile(full, body, { flag: 'wx', mode: 0o600 });
  }

  get(key: string) {
    return readFile(this.pathFor(key));
  }

  async delete(key: string) {
    await rm(this.pathFor(key), { force: true });
  }
}

/** Any S3-compatible bucket (Supabase Storage, AWS S3, Cloudflare R2, MinIO). The bucket must be private. */
export class S3FileStorage extends FileStorage {
  private readonly env = getEnv();
  private readonly client = new S3Client({
    endpoint: this.env.S3_ENDPOINT,
    region: this.env.S3_REGION,
    forcePathStyle: this.env.S3_FORCE_PATH_STYLE === 'true',
    credentials: { accessKeyId: this.env.S3_ACCESS_KEY_ID!, secretAccessKey: this.env.S3_SECRET_ACCESS_KEY! },
  });

  async put(key: string, body: Buffer, contentType: string) {
    assertSafeKey(key);
    await this.client.send(new PutObjectCommand({ Bucket: this.env.S3_BUCKET, Key: key, Body: body, ContentType: contentType }));
  }

  async get(key: string) {
    assertSafeKey(key);
    const res = await this.client.send(new GetObjectCommand({ Bucket: this.env.S3_BUCKET, Key: key }));
    if (!res.Body) throw new Error('Empty object');
    return Buffer.from(await res.Body.transformToByteArray());
  }

  async delete(key: string) {
    assertSafeKey(key);
    await this.client.send(new DeleteObjectCommand({ Bucket: this.env.S3_BUCKET, Key: key }));
  }
}

@Global()
@Module({
  providers: [
    {
      provide: FileStorage,
      useFactory: () => (getEnv().STORAGE_DRIVER === 's3' ? new S3FileStorage() : new LocalFileStorage()),
    },
  ],
  exports: [FileStorage],
})
export class StorageModule {}

